// Función helper para obtener traducciones de nuevos blogs
export function getNewBlogTranslation(id: number, language: string) {
  if (id < 40 || id > 82) return null;
  
  switch(language) {
    case 'en':
      return newBlogsEN[id as keyof typeof newBlogsEN];
    case 'fr':
      return newBlogsFR[id as keyof typeof newBlogsFR];
    case 'ar':
      return newBlogsAR[id as keyof typeof newBlogsAR];
    default:
      return null;
  }
}

